xhtml.p:
(* A four-step sequence written in structured text.

   Sequential function chart draws this as steps and transitions. The
   OpenPLC Editor importer skips SFC bodies with a warning, so this is the
   version that runs. The structure is the same: one step variable, one
   transition per step, and every step clears the outputs it does not own.

   Step 0  idle, waiting for start
   Step 1  pump running, waiting for stop
   Step 2  pump stopped, alarm latched until the fault clears
   Step 3  fault acknowledged, waiting for start to be released
*)

(* Every step clears the outputs it does not own. Without this, a coil keeps
   the value it had in the previous step and the logic stops being a sequence. *)
pump_run := FALSE;
alarm := FALSE;

CASE step OF
    0:  (* idle *)
        IF fault THEN
            step := 2;
        ELSIF start_cmd AND NOT stop_cmd THEN
            step := 1;
            run_ms := T#0s;
        END_IF;

    1:  (* pump running *)
        (* De-energize first and energize only in the ELSE. If the fault is
           checked after the output is set, the pump stays on for one scan
           with a fault present, which is the scan where the damage happens. *)
        IF fault THEN
            step := 2;
        ELSIF stop_cmd THEN
            step := 0;
        ELSE
            pump_run := TRUE;
            run_hours := run_hours + 0.001;
        END_IF;

    2:  (* fault, pump off, alarm latched *)
        alarm := TRUE;
        pump_run := FALSE;
        IF NOT fault THEN
            step := 3;
        END_IF;

    3:  (* fault cleared, alarm still latched until the operator acknowledges *)
        alarm := TRUE;
        IF NOT start_cmd THEN
            step := 0;
        END_IF;

ELSE
    (* An unknown step is a fault in itself. Go to the safe step. *)
    step := 2;
END_CASE;

(* The timer belongs to step 1. It resets whenever the sequence leaves it,
   so the elapsed value means "time in this step", not "time since boot". *)
step_timer(IN := (step = 1), PT := T#5s);
IF step_timer.Q THEN
    (* A pump that runs longer than five minutes without a stop command is
       treated as a fault, which lands the sequence in step 2. *)
    fault := TRUE;
END_IF;
